export const PREVIEW_IMAGE_FALLBACKS: Record<string, string> = {
  "/images/logo-header.jpg": "data:image/jpeg;base64,",
  "/images/logo-footer.jpg": "data:image/jpeg;base64,",
  "/images/clinic-exterior.jpg": "data:image/jpeg;base64,",
  "/images/doctor-profile.jpg": "data:image/jpeg;base64,",
  "/images/herbal-apothecary.jpg": "data:image/jpeg;base64,",
  "/images/doctor-treatment.jpg": "data:image/jpeg;base64,"
};

export function buildPreviewImageFallbackScript(): string {
  const serialized = JSON.stringify(PREVIEW_IMAGE_FALLBACKS).replace(/<\/script/gi, '<\\/script');
  return `(function(){var fallbacks=${serialized};window.__KH_IMG_FALLBACKS__=fallbacks;function normalizeSrc(raw){if(!raw)return'';try{return new URL(raw,window.location.href).pathname}catch(e){return raw}}function applyFallback(img){if(!img||img.dataset.fallbackApplied==='1')return false;var key=normalizeSrc(img.getAttribute('src')||img.src);var dataUri=fallbacks[key];if(!dataUri)return false;img.dataset.fallbackApplied='1';img.src=dataUri;return true}function sweep(){var imgs=document.querySelectorAll('img');for(var i=0;i<imgs.length;i++){var img=imgs[i];if(img.complete&&img.naturalWidth===0){applyFallback(img)}}}document.addEventListener('error',function(ev){var target=ev.target;if(target&&target.tagName==='IMG'){applyFallback(target)}},true);sweep();if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',sweep)}window.addEventListener('load',sweep);setTimeout(sweep,300)})();`;
}

